// --- Task ---

export interface TaskDetail {
  id: string;
  /** Brief title, max 50 chars, generated by LLM when creating the task. */
  title: string;
  description: string;
  priority: 'normal' | 'high';
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  createdAt: number;
  startedAt?: number;
  completedAt?: number;
  result?: string;
  error?: string;
  workerSessionId?: string;
  /**
   * The worker instance's OWN id (agent-…/cw-…) — the directory name under
   * `<sessionDir>/workers/` that holds this task's conversation.jsonl.
   * `workerSessionId` above is the engine's worker id (w-…), which never
   * matches the on-disk layout; this field keeps the transcript locatable
   * after the worker finished and the engine dropped its instance.
   */
  workerTranscriptId?: string;
  /** Worker type: 'puppet' (default) or a configured worker ID (e.g. 'claude-code'). */
  workerType?: string;
  /**
   * Multi-stage task: when true, the worker enters `idle` (not disposed) after
   * completion, so a follow-up task can be assigned to it with full context.
   * Controller decides this at add_task time.
   */
  multiStage?: boolean;
  /** When assigned to an existing idle worker: that worker's id. */
  assignToWorker?: string;
  /** When this task was dispatched to an idle worker: the worker id that ran it. */
  assignedFromWorkerId?: string;
  // --- Turn lineage (optional, audit only) ---
  /** Controller turn that created this task (the add_task turn). */
  turnId?: string;
  /** Root user turn of the chain that led to this task. */
  rootTurnId?: string;
  /** What triggered the creating turn (signal id), when known. */
  causationId?: string;
  /**
   * Turn id for the worker's execution of this task. Ephemeral — set by the
   * engine on the per-run task copy handed to the worker, never persisted.
   */
  executionTurnId?: string;
  /**
   * Workspace identity this task belongs to, as resolved by the workspace
   * registry (`path` is canonical, `slug` is stable). Optional: tasks written
   * before workspaces existed simply have no identity, and readers must fall
   * back to the session's own workspace.
   */
  workspace?: { path: string; slug: string };
  /**
   * Extra directories this ONE task may access, in addition to its workspace.
   * Declared at add_task time (allowedDirs), validated against the home
   * boundary and the denied-path list, and stored normalized + deduped.
   * Scoped to this task only — never inherited by other tasks. Optional:
   * absent means no extra directories were granted.
   */
  taskAllowedDirs?: string[];
}
